        start "${OPEN_URL}"
    else
        echo "Opening in browser manually: ${OPEN_URL}"
        echo "Run: xdg-open ${OPEN_URL}  (Linux)"
        echo "Run: open ${OPEN_URL}   (macOS)"
        echo "Run: start ${OPEN_URL}   (Windows)"
    fi

    echo ""
    echo "✅ Diagram generation complete!"
}

# Main execution
if [ ! -d "${OUTPUT_DIR}" ]; then
    mkdir -p "${OUTPUT_DIR}"
fi

# Read diagrams from input file
INPUT_FILE="${SCRIPT_DIR}/diagrams.md"

if [ -f "$INPUT_FILE" ]; then
    generate_diagrams "$INPUT_FILE"
else
    # Create sample diagram if input file doesn't exist
    echo "No input file found. Creating sample diagram..."
    generate_diagrams "${SCRIPT_DIR}/sample_diagram.md"
fi

