#!/bin/bash
# generate_diagrams.sh - Generate UML diagrams with mermaid.js
# Uses mermaid CDN to render diagrams in browser
# No sudo required - uses JavaScript library directly

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
INPUT_FILE="${SCRIPT_DIR}/diagrams.md"
DEFAULT_INPUT="${SCRIPT_DIR}/sample_diagram.md"

echo "=============================================="
echo "  FEM/Blender Integration - Diagram Generator"
echo "=============================================="
echo ""

# Check if input file is provided
if [ -n "$1" ]; then
    INPUT_FILE="$1"
    echo "Using custom input: ${INPUT_FILE}"
elif [ -f "$INPUT_FILE" ]; then
    echo "Using default input: ${INPUT_FILE}"
elif [ -f "$DEFAULT_INPUT" ]; then
    echo "Using sample: ${DEFAULT_INPUT}"
else
    echo "Creating sample diagram..."
    INPUT_FILE="${SCRIPT_DIR}/sample_diagram.md"
fi

OUTPUT_FILE="${SCRIPT_DIR}/diagrams_dark.html"

echo "Input file: ${INPUT_FILE}"
echo "Output file: ${OUTPUT_FILE}"
echo ""

# Read the mermaid diagram from file
DIAGRAM_CODE=$(cat "$INPUT_FILE" 2>/dev/null || echo "")

if [ -z "$DIAGRAM_CODE" ]; then
    echo "Error: Could not read from: ${INPUT_FILE}" >&2
    exit 1
fi

echo "Reading diagram code..."
echo ""

# Create HTML file with mermaid rendering
cat <<MERMAID_EOF > "$OUTPUT_FILE"
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>FEM/Blender Integration - UML Diagrams</title>
