            font-size: 1.8rem;
        }
        h2 {
            color: #569cd6;
            font-size: 1.4rem;
            margin-top: 30px;
            border-bottom: 2px solid #4ec9b0;
            padding-bottom: 5px;
        }
        .diagram-container {
            margin: 10px 0;
            padding: 15px;
            border: 1px solid #3c3c3c;
            border-radius: 5px;
            min-height: 200px;
        }
        .diagram-title {
            color: #cd3131;
            font-size: 1.1rem;
            margin-bottom: 10px;
            font-style: italic;
        }
        pre {
            white-space: pre-wrap;
            word-wrap: break-word;
        }
        footer {
            margin-top: 30px;
            text-align: center;
            color: #808080;
            font-size: 0.85rem;
        }
        footer a {
            color: #4ec9b0;
        }
    </style>
    <!-- Load mermaid library from CDN -->
    <script src="https://cdn.jsdelivr.net/npm/mermaid/dist/mermaid.min.js"></script>
</head>
<body>
    <div class="container">
        <h1>FEM/Blender Integration - UML Diagrams</h1>

        ${DIAGRAM_CODE}

        <footer>
            <p>Generated with mermaid.js | CC BY-NC-SA 4.0 | © 2026 intertino</p>
        </footer>
    </div>

    <script>
        // Initialize mermaid
        mermaid.initialize({
            startOnLoad: true,
            theme: 'dark',
            securityLevel: 'loose',
            fontFamily: 'Segoe UI, Tahoma, sans-serif',
            themeVariables: {
                primaryColor: '#1e1e1e',
                primaryTextColor: '#ffffff',
                primaryBorderColor: '#4ec9b0',
                lineColor: '#808080',
                secondaryColor: '#2d2d2d',
                tertiaryColor: '#2d2d2d'
            }
        });

        console.log('Mermaid initialized');
        console.log('Rendering diagrams on page load');
    </script>
</body>
</html>
MERMAID_EOF

echo "✅ Diagram HTML created: ${OUTPUT_FILE}"
echo ""

# Open in browser
OPEN_CMD=""
if command -v xdg-open &> /dev/null; then
    OPEN_CMD="xdg-open"
elif command -v open &> /dev/null; then
    OPEN_CMD="open"
elif command -v start &> /dev/null; then
    OPEN_CMD="start"
fi

if [ -n "$OPEN_CMD" ]; then
    echo "Opening diagram in browser..."
    $OPEN_CMD "$OUTPUT_FILE"
else
    echo "To view diagram manually, run:"
    echo "  ${OPEN_CMD} $OUTPUT_FILE"
    echo "  Or open: $OUTPUT_FILE"
fi

echo ""
echo "✅ Diagram generation complete!"
echo "=============================================="

